inline const EnumInfo *FindEnumInfo(std::string_view name) {
    const auto it = std::lower_bound(std::begin(kEnumInfos), std::end(kEnumInfos), name,
        [](const EnumInfo &info, std::string_view key) { return info.Name < key; });
    if (it != std::end(kEnumInfos) && it->Name == name)
        return &*it;
    return nullptr;
}
